        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeTextRecognizer.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface TextRecognizer: handle missing in uniffiClone")
            }
        },
        recognize: { (
            uniffiHandle: UInt64,
            bgra: RustBuffer,
            width: UInt32,
            height: UInt32,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
