                guard let uniffiObj = try? FfiConverterTypeTextRecognizer.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.recognize(
                     bgra: try FfiConverterData.lift(bgra),
                     width: try FfiConverterUInt32.lift(width),
                     height: try FfiConverterUInt32.lift(height)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterSequenceTypeOcrWord.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
