    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceTextRecognizer> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceTextRecognizer>.allocate(capacity: 1)
